CREATE TABLE IF NOT EXISTS guild_quests (
    Id TEXT NOT NULL PRIMARY KEY CHECK(Id=upper(Id) AND length(Id)=36 AND substr(Id,9,1)='-' AND substr(Id,14,1)='-' AND substr(Id,19,1)='-' AND substr(Id,24,1)='-' AND length(replace(Id,'-',''))=32 AND replace(Id,'-','') NOT GLOB '*[^0-9A-F]*' AND Id<>'00000000-0000-0000-0000-000000000000'),
    OperationId TEXT NOT NULL UNIQUE REFERENCES LongRunningOperations(Id) ON DELETE RESTRICT CHECK(OperationId=lower(OperationId) AND length(OperationId)=32 AND OperationId NOT GLOB '*[^0-9a-f]*' AND OperationId<>'00000000000000000000000000000000'),
    InstallationGeneration TEXT NOT NULL CHECK(InstallationGeneration=upper(InstallationGeneration) AND length(InstallationGeneration)=36 AND substr(InstallationGeneration,9,1)='-' AND substr(InstallationGeneration,14,1)='-' AND substr(InstallationGeneration,19,1)='-' AND substr(InstallationGeneration,24,1)='-' AND length(replace(InstallationGeneration,'-',''))=32 AND replace(InstallationGeneration,'-','') NOT GLOB '*[^0-9A-F]*' AND InstallationGeneration<>'00000000-0000-0000-0000-000000000000'),
    IssuerIdentity TEXT NOT NULL CHECK(IssuerIdentity=upper(IssuerIdentity) AND length(IssuerIdentity)=36 AND substr(IssuerIdentity,9,1)='-' AND substr(IssuerIdentity,14,1)='-' AND substr(IssuerIdentity,19,1)='-' AND substr(IssuerIdentity,24,1)='-' AND length(replace(IssuerIdentity,'-',''))=32 AND replace(IssuerIdentity,'-','') NOT GLOB '*[^0-9A-F]*' AND IssuerIdentity<>'00000000-0000-0000-0000-000000000000'),
    IssuerKindCode INTEGER NOT NULL CHECK(typeof(IssuerKindCode)='integer' AND IssuerKindCode IN(0,1)),
    IssuingStepId TEXT NOT NULL CHECK(IssuingStepId=upper(IssuingStepId) AND length(IssuingStepId)=36 AND substr(IssuingStepId,9,1)='-' AND substr(IssuingStepId,14,1)='-' AND substr(IssuingStepId,19,1)='-' AND substr(IssuingStepId,24,1)='-' AND length(replace(IssuingStepId,'-',''))=32 AND replace(IssuingStepId,'-','') NOT GLOB '*[^0-9A-F]*' AND IssuingStepId<>'00000000-0000-0000-0000-000000000000'),
    LogicalCallId TEXT NOT NULL CHECK(LogicalCallId=upper(LogicalCallId) AND length(LogicalCallId)=36 AND substr(LogicalCallId,9,1)='-' AND substr(LogicalCallId,14,1)='-' AND substr(LogicalCallId,19,1)='-' AND substr(LogicalCallId,24,1)='-' AND length(replace(LogicalCallId,'-',''))=32 AND replace(LogicalCallId,'-','') NOT GLOB '*[^0-9A-F]*' AND LogicalCallId<>'00000000-0000-0000-0000-000000000000'),
    MutationId TEXT NOT NULL CHECK(MutationId=upper(MutationId) AND length(MutationId)=36 AND substr(MutationId,9,1)='-' AND substr(MutationId,14,1)='-' AND substr(MutationId,19,1)='-' AND substr(MutationId,24,1)='-' AND length(replace(MutationId,'-',''))=32 AND replace(MutationId,'-','') NOT GLOB '*[^0-9A-F]*' AND MutationId<>'00000000-0000-0000-0000-000000000000'),
    IntentDigest BLOB NOT NULL CHECK(typeof(IntentDigest)='blob' AND length(IntentDigest)=32),
    ResolutionDigest BLOB NOT NULL CHECK(typeof(ResolutionDigest)='blob' AND length(ResolutionDigest)=32),
    RootQuestId TEXT NOT NULL CHECK(RootQuestId=upper(RootQuestId) AND length(RootQuestId)=36 AND substr(RootQuestId,9,1)='-' AND substr(RootQuestId,14,1)='-' AND substr(RootQuestId,19,1)='-' AND substr(RootQuestId,24,1)='-' AND length(replace(RootQuestId,'-',''))=32 AND replace(RootQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND RootQuestId<>'00000000-0000-0000-0000-000000000000'),
    ParentQuestId TEXT NULL CHECK(ParentQuestId IS NULL OR (ParentQuestId=upper(ParentQuestId) AND length(ParentQuestId)=36 AND substr(ParentQuestId,9,1)='-' AND substr(ParentQuestId,14,1)='-' AND substr(ParentQuestId,19,1)='-' AND substr(ParentQuestId,24,1)='-' AND length(replace(ParentQuestId,'-',''))=32 AND replace(ParentQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND ParentQuestId<>'00000000-0000-0000-0000-000000000000')),
    AgentId TEXT NOT NULL CHECK(AgentId=upper(AgentId) AND length(AgentId)=36 AND substr(AgentId,9,1)='-' AND substr(AgentId,14,1)='-' AND substr(AgentId,19,1)='-' AND substr(AgentId,24,1)='-' AND length(replace(AgentId,'-',''))=32 AND replace(AgentId,'-','') NOT GLOB '*[^0-9A-F]*' AND AgentId<>'00000000-0000-0000-0000-000000000000'),
    CardId TEXT NOT NULL CHECK(CardId=upper(CardId) AND length(CardId)=36 AND substr(CardId,9,1)='-' AND substr(CardId,14,1)='-' AND substr(CardId,19,1)='-' AND substr(CardId,24,1)='-' AND length(replace(CardId,'-',''))=32 AND replace(CardId,'-','') NOT GLOB '*[^0-9A-F]*' AND CardId<>'00000000-0000-0000-0000-000000000000'),
    CardRevision INTEGER NOT NULL CHECK(typeof(CardRevision)='integer' AND CardRevision>=1),
    RunId TEXT NOT NULL CHECK(RunId=upper(RunId) AND length(RunId)=36 AND substr(RunId,9,1)='-' AND substr(RunId,14,1)='-' AND substr(RunId,19,1)='-' AND substr(RunId,24,1)='-' AND length(replace(RunId,'-',''))=32 AND replace(RunId,'-','') NOT GLOB '*[^0-9A-F]*' AND RunId<>'00000000-0000-0000-0000-000000000000'),
    SignetId TEXT NOT NULL UNIQUE CHECK(SignetId=upper(SignetId) AND length(SignetId)=36 AND substr(SignetId,9,1)='-' AND substr(SignetId,14,1)='-' AND substr(SignetId,19,1)='-' AND substr(SignetId,24,1)='-' AND length(replace(SignetId,'-',''))=32 AND replace(SignetId,'-','') NOT GLOB '*[^0-9A-F]*' AND SignetId<>'00000000-0000-0000-0000-000000000000'),
    Name TEXT NULL CHECK(Name IS NULL OR length(CAST(Name AS BLOB))<=65536),
    SessionId TEXT NULL CHECK(SessionId IS NULL OR (SessionId=upper(SessionId) AND length(SessionId)=36 AND substr(SessionId,9,1)='-' AND substr(SessionId,14,1)='-' AND substr(SessionId,19,1)='-' AND substr(SessionId,24,1)='-' AND length(replace(SessionId,'-',''))=32 AND replace(SessionId,'-','') NOT GLOB '*[^0-9A-F]*' AND SessionId<>'00000000-0000-0000-0000-000000000000')),
    CampaignId TEXT NULL CHECK(CampaignId IS NULL OR (CampaignId=upper(CampaignId) AND length(CampaignId)=36 AND substr(CampaignId,9,1)='-' AND substr(CampaignId,14,1)='-' AND substr(CampaignId,19,1)='-' AND substr(CampaignId,24,1)='-' AND length(replace(CampaignId,'-',''))=32 AND replace(CampaignId,'-','') NOT GLOB '*[^0-9A-F]*' AND CampaignId<>'00000000-0000-0000-0000-000000000000')),
    WorkspaceId TEXT NULL CHECK(WorkspaceId IS NULL OR (WorkspaceId=upper(WorkspaceId) AND length(WorkspaceId)=36 AND substr(WorkspaceId,9,1)='-' AND substr(WorkspaceId,14,1)='-' AND substr(WorkspaceId,19,1)='-' AND substr(WorkspaceId,24,1)='-' AND length(replace(WorkspaceId,'-',''))=32 AND replace(WorkspaceId,'-','') NOT GLOB '*[^0-9A-F]*' AND WorkspaceId<>'00000000-0000-0000-0000-000000000000')),
    GoalContentId TEXT NOT NULL CHECK(GoalContentId=upper(GoalContentId) AND length(GoalContentId)=36 AND substr(GoalContentId,9,1)='-' AND substr(GoalContentId,14,1)='-' AND substr(GoalContentId,19,1)='-' AND substr(GoalContentId,24,1)='-' AND length(replace(GoalContentId,'-',''))=32 AND replace(GoalContentId,'-','') NOT GLOB '*[^0-9A-F]*' AND GoalContentId<>'00000000-0000-0000-0000-000000000000'),
    GoalRevision INTEGER NOT NULL CHECK(typeof(GoalRevision)='integer' AND GoalRevision>=1),
    GoalDigest BLOB NOT NULL CHECK(typeof(GoalDigest)='blob' AND length(GoalDigest)=32),
    GoalMimeType TEXT NOT NULL CHECK(length(CAST(GoalMimeType AS BLOB)) BETWEEN 1 AND 65536),
    GoalByteLength INTEGER NOT NULL CHECK(typeof(GoalByteLength)='integer' AND GoalByteLength BETWEEN 0 AND 65536),
    AllocationAccountId TEXT NOT NULL CHECK(AllocationAccountId=upper(AllocationAccountId) AND length(AllocationAccountId)=36 AND substr(AllocationAccountId,9,1)='-' AND substr(AllocationAccountId,14,1)='-' AND substr(AllocationAccountId,19,1)='-' AND substr(AllocationAccountId,24,1)='-' AND length(replace(AllocationAccountId,'-',''))=32 AND replace(AllocationAccountId,'-','') NOT GLOB '*[^0-9A-F]*' AND AllocationAccountId<>'00000000-0000-0000-0000-000000000000'),
    CreatedAtUtc TEXT NOT NULL,
    UpdatedAtUtc TEXT NOT NULL,
    IssuedSequence INTEGER NOT NULL UNIQUE CHECK(typeof(IssuedSequence)='integer' AND IssuedSequence>=1),
    Revision INTEGER NOT NULL CHECK(typeof(Revision)='integer' AND Revision>=1),
    LastNonterminalStateCode INTEGER NOT NULL CHECK(LastNonterminalStateCode IN(0,1,2)),
    WaitReasonCode INTEGER NULL CHECK(WaitReasonCode IS NULL OR WaitReasonCode IN(0,1,2,3,4)),
    QuestionId TEXT NULL CHECK(QuestionId IS NULL OR (QuestionId=upper(QuestionId) AND length(QuestionId)=36 AND substr(QuestionId,9,1)='-' AND substr(QuestionId,14,1)='-' AND substr(QuestionId,19,1)='-' AND substr(QuestionId,24,1)='-' AND length(replace(QuestionId,'-',''))=32 AND replace(QuestionId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestionId<>'00000000-0000-0000-0000-000000000000')),
    ContinuationId TEXT NULL CHECK(ContinuationId IS NULL OR (ContinuationId=upper(ContinuationId) AND length(ContinuationId)=36 AND substr(ContinuationId,9,1)='-' AND substr(ContinuationId,14,1)='-' AND substr(ContinuationId,19,1)='-' AND substr(ContinuationId,24,1)='-' AND length(replace(ContinuationId,'-',''))=32 AND replace(ContinuationId,'-','') NOT GLOB '*[^0-9A-F]*' AND ContinuationId<>'00000000-0000-0000-0000-000000000000')),
    CancellationRequested INTEGER NOT NULL CHECK(typeof(CancellationRequested)='integer' AND CancellationRequested IN(0,1)),
    CancellationConverged INTEGER NOT NULL CHECK(typeof(CancellationConverged)='integer' AND CancellationConverged IN(0,1)),
    AccountingStateCode INTEGER NOT NULL CHECK(AccountingStateCode IN(0,1,2)),
    Retired INTEGER NOT NULL DEFAULT 0 CHECK(typeof(Retired)='integer' AND Retired IN(0,1)),
    UNIQUE(InstallationGeneration,IssuerKindCode,IssuerIdentity,IssuingStepId,LogicalCallId)
);
